const urls = [
  "https://linkly.ai/zh/skills",
  "https://www.skills.sh/mattpocock/skills",
];
const res = await Promise.all(urls.map(u => tools.web_fetch({ url: u }).catch(e => ({ error: String(e), url: u }))));
for (const r of res as any[]) {
  console.log("#####", r.url ?? "", r.error ?? `status=${r.statusCode} kind=${r.body?.kind} trunc=${r.truncated}`);
  const c = String(r.body?.content ?? r.error ?? "");
  console.log(c.slice(0, 3000));
}

// Check locally installed skills on this machine for comparison
const g = await tools.glob({ pattern: "**/SKILL.md" }).catch(e => ({ paths: [] as string[], root: "" }));
console.log("\n=== local SKILL.md files ===");
console.log(g.paths.slice(0, 60).join("\n"));
